public sealed partial class ComponentConfirmation {
public static Game.Prefabs.TestComponent CurrentComponent;static int checks;static void Check(bool b,string message){if(!b)throw new Exception(message);checks++;}
private static void CheckComponentRemoval(ComponentConfirmation owner){
var imported=new Game.Prefabs.PrefabBase{Marker=true};var effect=new Game.Prefabs.TestComponent{prefab=imported};var unrelated=new Game.Prefabs.ComponentBase{prefab=imported};imported.components.Add(effect);imported.components.Add(unrelated);var inspector=new Game.UI.Editor.InspectorPanelSystem{Parent=imported,selectedObject=imported};owner.remove=typeof(Game.UI.Editor.InspectorPanelSystem).GetMethod("RemoveForTest",PrivateInstance);var req=new Request{World=inspector.World,Inspector=inspector,Prefab=imported,Parent=imported,Component=effect,Components=imported.components.ToArray(),Closure=new[]{typeof(Game.Prefabs.TestComponent)}};
MW.EditorTools.Modules.ComponentManager.Transfer.TransferTarget.Refreshes=0;owner.ApplyConfirmedComponentRemoval(req);
Check(!imported.Marker&&inspector.Removals==1,"Imported copied effects marker clears after deferred component deletion and refresh");Check(imported.components.Count==1&&ReferenceEquals(imported.components[0],unrelated),"Unrelated copied components retained");Check(imported.isDirty&&inspector.Refreshes==1&&inspector.Changes==0,"Dirty source and inspector refresh without stale native OnValueChanged");Check(MW.EditorTools.Modules.ComponentManager.Transfer.TransferTarget.Refreshes==1,"One native prefab refresh after confirmed deletion");
imported.components.Insert(0,effect);req.Components=imported.components.ToArray();inspector.FailRemoval=true;try{owner.ApplyConfirmedComponentRemoval(req);throw new Exception("Expected removal failure");}catch(TargetInvocationException){}Check(imported.components.Contains(effect)&&MW.EditorTools.Modules.ComponentManager.Transfer.TransferTarget.Refreshes==1,"Native removal exception does not refresh an unmodified source");inspector.FailRemoval=false;
imported.isReadOnly=true;try{owner.ApplyConfirmedComponentRemoval(req);throw new Exception("Expected readonly refusal");}catch(InvalidOperationException){}Check(imported.components.Contains(effect)&&inspector.Removals==1,"Refresh target preflight refuses readonly source before deletion");imported.isReadOnly=false;
owner.collect=typeof(Game.UI.Editor.InspectorPanelSystem).GetMethod("CollectForTest",BindingFlags.NonPublic|BindingFlags.Static);owner.Invalidate();imported.Marker=true;var ui=Game.SceneFlow.GameManager.instance.userInterface.appBindings;int removes=inspector.Removals,refreshes=MW.EditorTools.Modules.ComponentManager.Transfer.TransferTarget.Refreshes;
Check(!owner.Intercept(inspector,effect)&&imported.components.Contains(effect)&&inspector.Removals==removes,"Opening component confirmation leaves copied effects intact");ui.Answer(1);owner.Update();Check(imported.components.Contains(effect)&&MW.EditorTools.Modules.ComponentManager.Transfer.TransferTarget.Refreshes==refreshes,"Cancelled component removal performs no native refresh");
Check(!owner.Intercept(inspector,effect),"Confirmed effect deletion remains deferred");ui.Answer(0);owner.Update();Check(!imported.components.Contains(effect)&&!imported.Marker&&MW.EditorTools.Modules.ComponentManager.Transfer.TransferTarget.Refreshes==refreshes+1,"Actual deferred dialog Update removes copied effect and refreshes marker once");ui.Answer(0);owner.Update();Check(inspector.Removals==removes+1&&MW.EditorTools.Modules.ComponentManager.Transfer.TransferTarget.Refreshes==refreshes+1,"Repeated dialog callback cannot repeat removal or native refresh");
}
public static void Main(){
var owner=new ComponentConfirmation();active=owner;owner.settings=new MW.EditorTools.Settings.EditorToolsSettings();owner.mainThread=Environment.CurrentManagedThreadId;owner.installed=true;owner.parent=typeof(Game.UI.Editor.InspectorPanelSystem).GetField("Parent");owner.callback=typeof(Game.UI.AppBindings).GetField("Callback");owner.dismissibleCallback=typeof(Game.UI.AppBindings).GetField("Dismissible");var root=new Game.Prefabs.PrefabBase();var c=new Game.Prefabs.TestComponent{prefab=root};CurrentComponent=c;root.components.Add(c);var inspector=new Game.UI.Editor.InspectorPanelSystem{Parent=root,selectedObject=root};owner.clearInspector=inspector;owner.clearMethod=typeof(Game.UI.Widgets.PagedList).GetMethod("Clear");owner.listChanged=typeof(Game.UI.Editor.InspectorPanelSystem).GetMethod("OnValueChanged",PrivateInstance);var list=new Game.UI.Widgets.PagedList{locked=true,adapter=new(){accessor=new Game.Reflection.Accessor{Read=()=>c.Items}}};var ui=Game.SceneFlow.GameManager.instance.userInterface.appBindings;
Check(!BeforeClear(list)&&list.Clears==0&&c.Items.Length==3,"Click shows confirmation without mutation");Check(ui.Shows==1&&ui.Dialog.Message.Contains("all 3")&&ui.Dialog.Message.Contains("hidden by search"),"Dialog reports underlying total and hidden entries");Check(SuppressClearChange(list),"Recovery postfix suppresses pending Clear to preserve history");Check(!SuppressClearChange(null),"Null unrelated change is not suppressed");Check(!BeforeClearChanged(list),"Original click cannot trigger prefab change while pending");Check(BeforeClearChanged(new Game.UI.Widgets.PagedList()),"Unrelated widget event remains allowed");Check(!BeforeClear(list)&&ui.Shows==1,"Repeated click cannot create second dialog");var request=owner.pending;Check(owner.ValidClear(request),"Unchanged list remains confirmable");ui.Answer(1);owner.answers.TryDequeue(out var cancel);Check(!owner.gate.Consume(cancel.Token,cancel.Action==0,0)&&list.Clears==0,"Cancel authorises no clear");owner.pending=null;Check(!owner.gate.Consume(request.Token,true,0),"Late confirm after cancellation rejected");
BeforeClear(list);request=owner.pending;c.Items[0]="edited";Check(!owner.ValidClear(request),"In-place edit invalidates request");c.Items[0]="one";var original=c.Items;c.Items=c.Items.ToArray();Check(!owner.ValidClear(request),"Equal replacement storage invalidates request");c.Items=original;inspector.selectedObject=new object();Check(!owner.ValidClear(request),"Selection switch invalidates request");inspector.selectedObject=root;root.isReadOnly=true;Check(!owner.ValidClear(request),"Read-only change invalidates request");root.isReadOnly=false;list.locked=true;Check(owner.ValidClear(request),"Expansion lock does not prohibit confirmed deletion");list.locked=true;HarmonyLib.Harmony.Conflict=true;Check(!owner.ValidClear(request),"Foreign patch invalidates request");HarmonyLib.Harmony.Conflict=false;owner.Invalidate();
BeforeClear(list);request=owner.pending;ui.Answer(0);owner.answers.TryDequeue(out var yes);Check(owner.gate.Consume(yes.Token,yes.Action==0,0)&&owner.ValidClear(request),"Current confirm authorises validated list");owner.pending=null;owner.bypass=request;Check(BeforeClear(list)&&owner.bypass==null,"Bypass consumed once");owner.ApplyClear(request);Check(c.Items.Length==0&&list.Clears==1&&inspector.Changes==1,"Confirmed clear invokes native action and change notification once");Check(BeforeClear(list),"Empty list needs no confirmation");owner.settings.confirmation=false;c.Items=new[]{"one"};Check(BeforeClear(list),"Disabled setting retains vanilla clear");owner.settings.confirmation=true;var unrelated=new Game.UI.Widgets.PagedList{adapter=new(){accessor=new Game.Reflection.Accessor{Read=()=>new[]{"unrelated"}}}};Check(BeforeClear(unrelated),"Unmapped lists retain vanilla behaviour");
c.Items=new[]{"one","two"};BeforeClear(list);ui.Answer(0);owner.Update();Check(!SuppressClearChange(list),"Confirmed Clear allows native notification and history invalidation");Check(c.Items.Length==0&&list.Clears==2&&inspector.Changes==2,"Actual confirmation Update dispatches Clear and native change, not component removal");c.Items=new[]{"one","two"};BeforeClear(list);ui.Answer(1);owner.Update();Check(c.Items.Length==2&&list.Clears==2,"Actual Update cancellation preserves entries");BeforeClear(list);c.Items[0]="changed";ui.Answer(0);owner.Update();Check(c.Items.Length==2&&list.Clears==2,"Actual Update rejects changed list before confirmed mutation");CheckComponentRemoval(owner);Console.WriteLine("PASS: "+checks+" actual-source component removal and Clear confirmation checks with managed UI stubs; native dialog and snapshot integration pending.");
}
}
